<script lang="ts">
import { tick } from 'svelte';
import type { ApexConfig, ApexLocale, ApexSavedInquiry } from '../../../../core/src/apex/mod.ts';
import { whatsappUrl } from '../../../../core/src/apex/mod.ts';
import type { ApexStore } from '../../../../state/src/stores/apex.svelte.ts';
import { accountDate, accountInitials, accountStatus } from './presentation.ts';
import RecordDetails from './RecordDetails.svelte';
import { useResolver } from '../url.ts';
let { config, locale, store }: { config: ApexConfig; locale: ApexLocale; store: ApexStore } = $props();
const resolve = useResolver();
type AccountTab = 'inquiries' | 'reservations' | 'trips';
const tabs: AccountTab[] = ['inquiries', 'reservations', 'trips'];
let tab = $state<AccountTab>('inquiries');
let selected = $state<ApexSavedInquiry | null>(null);
let profileDialog = $state<HTMLDialogElement>();
let tabButtons = $state<Partial<Record<AccountTab, HTMLButtonElement>>>({});
let all = $derived(store.savedInquiries);
let inquiries = $derived(all.filter(item => ['draft','requested','quoted'].includes(item.status)));
let reservations = $derived(all.filter(item => item.status === 'confirmed'));
let trips = $derived(all.filter(item => ['completed','cancelled'].includes(item.status)));
let records = $derived(tab === 'inquiries' ? inquiries : tab === 'reservations' ? reservations : trips);
let nextAdventure = $derived([...reservations].sort((a,b)=>a.date.localeCompare(b.date))[0] ?? [...inquiries].sort((a,b)=>a.date.localeCompare(b.date))[0]);
let nextExperience = $derived(config.experiences.find(item => item.id === nextAdventure?.experienceId));
let firstName = $derived(store.user?.name?.trim().split(/\s+/)[0] || store.user?.email.split('@')[0] || 'APEX');
const ui = (es:string,en:string) => locale === 'es' ? es : en;
const tabLabel = (value: AccountTab) => value === 'inquiries' ? ui('Consultas','Inquiries') : value === 'reservations' ? ui('Reservas','Reservations') : ui('Viajes','Trips');
const count = (value: AccountTab) => value === 'inquiries' ? inquiries.length : value === 'reservations' ? reservations.length : trips.length;
const image = (record: ApexSavedInquiry) => config.experiences.find(item=>item.id===record.experienceId)?.image ?? config.brand.background;
const title = (record: ApexSavedInquiry) => config.experiences.find(item=>item.id===record.experienceId)?.title[locale] ?? record.experienceId;
async function navigateTab(event: KeyboardEvent, value: AccountTab) { let index=tabs.indexOf(value); if(event.key==='ArrowRight')index=(index+1)%tabs.length;else if(event.key==='ArrowLeft')index=(index-1+tabs.length)%tabs.length;else if(event.key==='Home')index=0;else if(event.key==='End')index=tabs.length-1;else return;event.preventDefault();tab=tabs[index];await tick();tabButtons[tab]?.focus(); }
$effect(()=>{store.user?.id;store.accountMode;selected=null;tab='inquiries';profileDialog?.close();});
</script>
<section class="account-dashboard wrap">
 <div class="account-topbar"><a href={resolve('/#experiencias')} class="account-back">← {ui('Volver a explorar','Back to exploring')}</a><div>{#if store.isDemo}<span class="account-demo-chip"><span></span>{ui('Modo demostración','Demonstration mode')}</span>{:else}<span class="account-live-chip">{ui('Mi cuenta APEX','My APEX account')}</span>{/if}<button type="button" class="account-signout" disabled={store.busy} onclick={()=>store.signOut()}>{ui('Cerrar sesión','Sign out')} <span aria-hidden="true">↗</span></button></div></div>
 <div class="account-welcome-grid"><div class="account-welcome"><p class="account-kicker">{ui('TU UNIVERSO APEX','YOUR APEX UNIVERSE')}</p><h1>{ui('Hola','Hello')}, {firstName}<span>.</span></h1><h2>{config.account?.heroTitle[locale] ?? ui('Tu próxima historia empieza aquí.','Your next story starts here.')}</h2><p>{config.account?.heroIntro[locale] ?? ui('Todo lo que estás planeando, lo que viene y los momentos que ya son tuyos.','Everything you’re planning, what’s coming next and the moments that are already yours.')}</p><a class="button" href={resolve('/#experiencias')}>{ui('Encuentra tu próxima aventura','Find your next adventure')} ↗</a>{#if store.isDemo}<p class="account-welcome-demo"><span>◌</span>{ui('Estás explorando datos de ejemplo. No hay reservas ni pagos reales.','You are exploring sample data. There are no real bookings or payments.')}</p>{/if}</div>
 <div class="account-next-card"><img src={nextExperience?.image ?? config.account?.heroImage ?? config.brand.background} alt={nextExperience?.title[locale] ?? ''}/><div class="account-next-shade"></div><div class="account-next-top"><span class="account-next-label">{ui('UN PLAN EN EL HORIZONTE','A PLAN ON THE HORIZON')}</span>{#if store.isDemo}<span class="account-sample-tag">{ui('Ejemplo','Example')}</span>{/if}</div><div class="account-next-copy">{#if nextAdventure}<span class="account-status-chip" data-status={nextAdventure.status}>{accountStatus(nextAdventure.status,locale)}</span><h3>{nextExperience?.title[locale] ?? nextAdventure.experienceId}</h3><p>{accountDate(nextAdventure.date,locale)} <span>·</span> {nextAdventure.people} {ui('personas','people')}</p><button type="button" class="account-next-link" onclick={()=>selected=nextAdventure}>{ui('Ver mi próxima salida','View my next outing')} <span>↗</span></button>{:else}<h3>{ui('Elige tu siguiente historia.','Choose your next story.')}</h3><p>{ui('El primer paso es salir de lo de siempre.','The first step is leaving the everyday behind.')}</p><a href={resolve('/#experiencias')} class="account-next-link">{ui('Explorar destinos','Explore destinations')} ↗</a>{/if}</div></div></div>
 <div class="account-overview" aria-label={ui('Resumen de mi cuenta','My account overview')}>{#each tabs as value,i}<button class="account-overview-card" class:active={tab===value} onclick={()=>tab=value}><span class="account-overview-icon" aria-hidden="true">{['↗','◇','⌁'][i]}</span><span class="account-overview-text"><strong>{String(count(value)).padStart(2,'0')}</strong><span>{tabLabel(value)}</span></span><span class="account-overview-arrow" aria-hidden="true">→</span></button>{/each}</div>
 <div class="account-workspace"><aside class="account-sidebar"><section class="account-profile-card"><div class="account-avatar">{accountInitials(store.user?.name || store.user?.email || '')}</div><div><p class="account-profile-name">{store.user?.name || ui('Tu cuenta APEX','Your APEX account')}</p><p class="account-profile-email">{store.user?.email}</p></div><span class="account-profile-type">{store.isDemo?ui('Perfil de ejemplo','Example profile'):ui('Área personal','Personal area')}</span><button class="account-profile-link" type="button" onclick={()=>profileDialog?.showModal()}>{ui('Ver mi perfil','View my profile')} <span>↗</span></button></section><section class="account-help-card"><span class="account-help-icon" aria-hidden="true">✦</span><h3>{ui('Un plan con tu sello.','A plan with your signature.')}</h3><p>{ui('¿Una celebración, una idea o una duda? Estamos a una conversación.','A celebration, an idea or a question? We are a conversation away.')}</p><a href={whatsappUrl(config,ui('Hola APEX, quisiera consultar una experiencia.','Hi APEX, I would like to inquire about an experience.'))} target="_blank" rel="noopener noreferrer">{ui('Hablemos','Let’s talk')} ↗</a></section></aside>
 <section class="account-records-section" aria-labelledby="account-records-title"><div class="account-section-heading"><div><p class="account-kicker">{ui('CADA HISTORIA TIENE SU MOMENTO','EVERY STORY HAS ITS MOMENT')}</p><h2 id="account-records-title">{ui('Tus experiencias.','Your experiences.')}</h2></div><button class="account-refresh" type="button" disabled={store.busy} onclick={()=>store.loadInquiries()} aria-label={ui('Actualizar historial','Refresh history')}><span class:spinning={store.busy}>↻</span>{ui('Actualizar','Refresh')}</button></div>
 <div class="account-record-tabs" role="tablist" aria-label={ui('Historial de experiencias','Experience history')}>{#each tabs as value}<button bind:this={tabButtons[value]} id={`account-tab-${value}`} role="tab" aria-selected={tab===value} aria-controls="account-record-panel" tabindex={tab===value?0:-1} class:active={tab===value} onclick={()=>tab=value} onkeydown={(event)=>navigateTab(event,value)}>{tabLabel(value)}<span>{count(value)}</span></button>{/each}</div>
 <div id="account-record-panel" class="account-record-panel" role="tabpanel" aria-labelledby={`account-tab-${tab}`} tabindex="0">
 {#if store.busy}<div class="account-loading" role="status"><span class="account-loading-ring"></span><p>{ui('Preparando tus experiencias…','Preparing your experiences…')}</p></div>
 {:else if records.length}<div class="account-record-list">{#each records as record}<article class="account-record-card"><button class="account-record-photo" type="button" onclick={()=>selected=record} aria-label={`${ui('Ver detalle de','View details for')} ${title(record)}`}><img src={image(record)} alt={title(record)} loading="lazy"/>{#if store.isDemo}<span>{ui('EJEMPLO','EXAMPLE')}</span>{/if}</button><div class="account-record-copy"><div class="account-record-topline"><span class="account-status-chip" data-status={record.status}>{accountStatus(record.status,locale)}</span><span class="account-record-reference">{record.reference ?? ui('Consulta','Inquiry')}</span></div><button type="button" class="account-record-title" onclick={()=>selected=record}>{title(record)}</button><div class="account-record-meta"><span><svg viewBox="0 0 20 20" aria-hidden="true"><rect x="3" y="4" width="14" height="13" rx="2"/><path d="M6 2v4m8-4v4M3 8h14"/></svg>{accountDate(record.date,locale,true)}</span><span><svg viewBox="0 0 20 20" aria-hidden="true"><circle cx="7" cy="6" r="3"/><path d="M1 17v-2a6 6 0 0 1 12 0v2m2-13a3 3 0 0 1 0 6m1 2a5 5 0 0 1 3 5"/></svg>{record.people} {ui('personas','people')}</span></div>{#if record.quote}<p class="account-record-quote">{record.quote}</p>{:else}<p class="account-record-description">{ui('Tu siguiente aventura empieza con una conversación.','Your next adventure starts with a conversation.')}</p>{/if}<div class="account-record-bottom"><span>{record.language==='es'?'Español':'English'}{store.isDemo?` · ${ui('Datos de ejemplo','Sample data')}`:''}</span><button type="button" onclick={()=>selected=record}>{ui('Ver detalle','View details')} <span>↗</span></button></div></div></article>{/each}</div>
 {:else}<div class="account-empty"><span class="account-empty-art" aria-hidden="true">{tab==='inquiries'?'↗':tab==='reservations'?'◇':'⌁'}</span><h3>{tab==='inquiries'?ui('Aquí empieza una nueva historia.','A new story starts here.'):tab==='reservations'?ui('Lo mejor aún está por venir.','The best is still ahead.'):ui('Tus recuerdos tendrán su lugar.','Your memories will have a place.')}</h3><p>{tab==='inquiries'?ui('Guarda una consulta desde el resumen de una experiencia y vuelve a ella cuando quieras.','Save an inquiry from an experience summary and return whenever you like.'):tab==='reservations'?ui('Cuando APEX confirme tu salida, encontrarás aquí todos los detalles.','When APEX confirms your outing, you will find all the details here.'):ui('Las experiencias completadas aparecerán aquí para que vuelvas a tu historia.','Completed experiences will appear here so you can return to your story.')}</p><a class="button outline" href={resolve('/#experiencias')}>{ui('Explorar experiencias','Explore experiences')} ↗</a></div>{/if}
 </div>{#if store.error}<p class="account-feedback error" role="alert">{store.error}</p>{/if}{#if store.message}<p class="account-feedback" role="status">{store.message}</p>{/if}
 </section></div>
</section>
<RecordDetails {config} {locale} record={selected} demo={store.isDemo} onClose={()=>selected=null} canRemove={!!(store.isDemo&&selected?.status==='draft'&&selected.id.startsWith('demo-inquiry-'))} onRemove={async()=>{if(!selected)return;await store.removeDemoInquiry(selected.id);if(!store.error)selected=null;}}/>
<dialog bind:this={profileDialog} class="account-profile-dialog" aria-labelledby="account-profile-title"><button class="account-dialog-close" type="button" onclick={()=>profileDialog?.close()} aria-label={ui('Cerrar perfil','Close profile')}>×</button><div class="account-avatar">{accountInitials(store.user?.name || store.user?.email || '')}</div><p class="account-kicker">{ui('TU PERFIL APEX','YOUR APEX PROFILE')}{store.isDemo?` · ${ui('EJEMPLO','EXAMPLE')}`:''}</p><h2 id="account-profile-title">{store.user?.name || ui('Tu cuenta','Your account')}</h2><dl><div><dt>{ui('Correo electrónico','Email address')}</dt><dd>{store.user?.email}</dd></div>{#if store.isDemo&&config.account?.profileLocation}<div><dt>{ui('Ubicación','Location')}</dt><dd>{config.account.profileLocation}</dd></div>{/if}{#if store.isDemo&&config.account?.memberSince}<div><dt>{ui('En el universo APEX desde','In the APEX universe since')}</dt><dd>{config.account.memberSince}</dd></div>{/if}<div><dt>{ui('Tipo de cuenta','Account type')}</dt><dd>{store.isDemo?ui('Cuenta de demostración · solo en este navegador','Demonstration account · only in this browser'):ui('Cuenta personal APEX','Personal APEX account')}</dd></div></dl>{#if store.isDemo}<p class="account-detail-note">{ui('Este perfil y sus experiencias son datos de ejemplo. No representan una identidad o reserva real.','This profile and its experiences are sample data. They do not represent a real identity or booking.')}</p>{/if}<button class="button" type="button" onclick={()=>profileDialog?.close()}>{ui('Volver a mis experiencias','Back to my experiences')} ↗</button>{#if store.isDemo}<button class="account-reset-example" type="button" disabled={store.busy} onclick={async()=>{await store.resetDemoAccount();profileDialog?.close();selected=null;tab='inquiries';}}>{ui('Restablecer datos de ejemplo','Reset example data')} ↻</button><p class="account-reset-note">{ui('Restaura las experiencias ficticias iniciales de este navegador.','Restores this browser’s initial fictional experiences.')}</p>{/if}</dialog>
